const jabatanSelect=document.getElementById("jabatan-select"),divisiWrapper=document.getElementById("divisi-wrapper"),divisiSelect=document.getElementById("divisi-select");function toggleDivisi(){const e=jabatanSelect.value;"ketua divisi"===e||"anggota divisi"===e?(divisiWrapper.classList.remove("hidden"),divisiSelect.setAttribute("required","required")):(divisiWrapper.classList.add("hidden"),divisiSelect.removeAttribute("required"),divisiSelect.value="")}window.addEventListener("DOMContentLoaded",toggleDivisi),jabatanSelect.addEventListener("change",toggleDivisi);const fileInput=document.getElementById("foto-input"),fileNameDisplay=document.getElementById("file-name"),fileSizeDisplay=document.getElementById("file-size"),iconContainer=document.getElementById("icon-container"),dropzone=document.getElementById("dropzone-visual");fileInput.addEventListener("change",function(){if(this.files&&this.files[0]){const e=this.files[0];fileNameDisplay.innerText=e.name,fileNameDisplay.classList.remove("text-slate-700"),fileNameDisplay.classList.add("text-rose-600");const i=(e.size/1048576).toFixed(2);fileSizeDisplay.innerText=`Ukuran: ${i} MB - Siap upload!`,dropzone.classList.remove("border-slate-200","bg-slate-50"),dropzone.classList.add("border-rose-500","bg-rose-50"),iconContainer.innerHTML='\n                    <svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6 text-emerald-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">\n                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7" />\n                    </svg>\n                ',iconContainer.classList.add("bg-emerald-50")}});